const attr=esc;const clone=value=>JSON.parse(JSON.stringify(value));const id=()=>('id-'+(globalThis.crypto?.randomUUID?.()||Math.random().toString(36).slice(2,14))).replace(/[^a-zA-Z0-9_-]/g,'');
