// A restarted local server mints a new CSRF token; the rejected request never ran, so fetch the fresh token and retry once.
const freshCsrf=async()=>{try{const response=await fetch('/',{cache:'no-store'});return (await response.text()).match(/<meta name="jev-csrf" content="([a-f0-9]{64})"/)?.[1]}catch{return undefined}};
