function badge(text,kind=''){return '<span class="badge '+kind+'">'+esc(text)+'</span>'}
function field(label,name,value='',type='text',help='',attrs='',suffix=''){const fieldId='f-'+name+(suffix?'-'+suffix:'');return '<div class="field"><label for="'+esc(fieldId)+'">'+esc(label)+'</label><input id="'+esc(fieldId)+'" name="'+esc(name)+'" type="'+type+'" value="'+attr(value)+'" '+attrs+'>'+ (help?'<small>'+esc(help)+'</small>':'')+'</div>'}
function area(label,name,value='',help='',rows='4',suffix=''){const fieldId='f-'+name+(suffix?'-'+suffix:'');return '<div class="field"><label for="'+esc(fieldId)+'">'+esc(label)+'</label><textarea id="'+esc(fieldId)+'" name="'+esc(name)+'" rows="'+rows+'">'+esc(value)+'</textarea>'+(help?'<small>'+esc(help)+'</small>':'')+'</div>'}
function select(name,options,value,label,suffix=''){const fieldId='f-'+name+(suffix?'-'+suffix:'');return '<div class="field"><label for="'+esc(fieldId)+'">'+esc(label)+'</label><select id="'+esc(fieldId)+'" name="'+esc(name)+'"><button type="button"><selectedcontent></selectedcontent></button>'+options.map(o=>'<option value="'+attr(o.value)+'" '+(o.value===value?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></div>'}
function panel(title,desc,body,tools=''){return '<section class="panel"><div class="panelhead"><div><h2>'+esc(title)+'</h2>'+(desc?'<p>'+esc(desc)+'</p>':'')+'</div>'+tools+'</div>'+body+'</section>'}
function empty(title,desc,action=''){return '<div class="empty"><strong>'+esc(title)+'</strong><p>'+esc(desc)+'</p>'+action+'</div>'}

function project(){return S.doc?.projects?.find(p=>p.id===S.projectId)}
function projectCohorts(){const p=project();return p?S.doc.cohorts.filter(c=>p.cohortIds.includes(c.id)):[]}
function projectPipelines(){const p=project();return p?S.doc.pipelines.filter(x=>p.pipelineIds.includes(x.id)):[]}
function projectRuns(projectId=S.projectId){return S.doc.projects.some(p=>p.id===projectId)?(S.snap.runs||[]).filter(r=>r.projectId===projectId):[]}
function ownCohort(c){const p=project();if(!p)throw Error('Open a project first.');if(!p.cohortIds.includes(c.id))p.cohortIds.push(c.id)}
function ownPipeline(pipeline){const p=project();if(!p)throw Error('Open a project first.');if(!p.pipelineIds.includes(pipeline.id))p.pipelineIds.push(pipeline.id)}
const projectViewKeys=['sections','segmentId','cohortSection','personaOpen','personaPage','personaGroup','personaFilter','distributionField','distributionWeighted','targetDraft','targetOriginalField','personaRegenOpen','personaRegenPrompt','cohortReturn','tab','pipelineId','studyLibrary','studyComposer','stageId','cohortId','personId','preferredCohortId','newQuestion','cohortComposer','cohortInlineTarget','cohortTarget','cohortPrompt','cohortSize','cohortLastSize','localPrompt','localJob','localError','localPollError','proposalApplied'];
function selectProject(projectId,library=false){
  if(S.localStarting)throw Error('Wait for the drafting request to finish before switching projects.');
  if(S.projectId){const view={};for(const key of projectViewKeys)view[key]=S[key];S.projectViews[S.projectId]=view}
  S.projectId=projectId;S.projectComposer=false;S.plan=null;S.cohortDeletion=null;S.projectDeletion=null;S.studyDeletion=null;
  Object.assign(S,{sections:{},segmentId:null,cohortSection:'people',personaOpen:false,personaPage:0,personaGroup:'',personaFilter:null,distributionField:'age',distributionWeighted:false,targetDraft:null,targetOriginalField:null,personaRegenOpen:false,personaRegenPrompt:'',cohortReturn:null,tab:'studies',pipelineId:null,studyLibrary:false,studyComposer:false,stageId:null,cohortId:null,personId:null,preferredCohortId:null,newQuestion:'',cohortComposer:false,cohortInlineTarget:null,cohortTarget:null,cohortPrompt:'',cohortSize:8,cohortLastSize:8,localPrompt:'',localJob:null,localError:null,localPollError:null,proposalApplied:false},S.projectViews[projectId]||{});
  if(library)Object.assign(S,{tab:'studies',pipelineId:null,stageId:null,studyLibrary:true,studyComposer:false});
  retainSelections();render();
  if(projectId){if(S.localJob?.status==='running')void pollLocalJob(S.localJob.id);void loadLocalAgents()}
}
function projectNavigation(){return '<div class="project-navigation">'+workspaceBreadcrumbs()+'</div>'}
function listRow(act,item,label,title,subtitle,meta,trailing,itemClass,buttonClass=''){return '<div class="list-item '+itemClass+'"><button type="button" class="listrow list-open'+(buttonClass?' '+buttonClass:'')+'" data-act="'+act+'" data-id="'+attr(item.id)+'" aria-label="'+attr(label)+'"><span class="list-body"><strong>'+esc(title)+'</strong>'+(subtitle?'<span class="list-sub">'+esc(subtitle)+'</span>':'')+(meta.length?'<span class="list-meta">'+meta.map(m=>'<small>'+esc(m)+'</small>').join('<span aria-hidden="true">·</span>')+'</span>':'')+'</span>'+icon('right')+'</button>'+trailing+'</div>'}
function listDeleteButton(act,item,label){return '<button type="button" class="button small danger icon-button list-delete" data-act="'+act+'" data-id="'+attr(item.id)+'" aria-label="'+attr(label)+'" title="'+attr(label.split(':')[0])+'">'+icon('trash')+'</button>'}
function projects(){
  if(S.projectComposer)return header('New project','Give this research a name and a brief.')+'<div class="project-composer">'+panel('Project details','','<form data-form="new-project">'+field('Project name','projectName',S.projectName,'text','','required maxlength="160"')+area('Research brief','projectBrief',S.projectBrief,'What do you want to learn or decide?','4')+'<div class="row"><button class="button primary" type="submit">Create project</button><button class="button" type="button" data-act="cancel-project">Cancel</button></div></form>')+'</div>';
  const page=pageItems(S.doc.projects,'projects',viewportPageSize(4,1));
  const rows=page.items.map(p=>S.projectRename===p.id?projectRenameRow(p):listRow('open-project',p,'Open project: '+p.name,p.name,p.description||'Add a brief to define this research.',[plural(p.cohortIds.length,'cohort'),p.pipelineIds.length+' '+(p.pipelineIds.length===1?'study':'studies'),plural(projectRuns(p.id).length,'run')],projectRenameButton(p)+listDeleteButton('delete-project',p,'Delete project: '+p.name),'project-list-row')).join('');
  return header('Projects','Keep cohorts, studies, and results together.',(S.dirty?saveButton():'')+'<button class="button primary" data-act="new-project">New project</button>')+'<section aria-label="Projects">'+(rows?'<div class="list">'+rows+'</div>'+page.controls:empty('Start your first project','Choose New project to name the decision you want to explore.'))+'</section>';
}
function projectSettings(){const p=project();return header('Project settings','Name the research and describe its goal.',saveButton())+panel('Research brief','','<form data-form="project-settings">'+field('Project name','name',p.name,'text','','required maxlength="160"')+area('Research brief','description',p.description,'','5')+'<button class="button primary icon-button" type="submit" title="Save project details" aria-label="Save project details">'+icon('check')+'</button></form>')}
async function createProject(form){
  const d=new FormData(form),name=String(d.get('projectName')||'').trim();if(!name)throw Error('Name your project first.');
  const p={id:id(),name,description:String(d.get('projectBrief')||'').trim(),cohortIds:[],pipelineIds:[]};S.doc.projects.push(p);S.dirty=true;S.projectComposer=false;S.projectName='';S.projectBrief='';await save();if(!S.dirty)landOnProject(p.id);
}

function pipeline(){return projectPipelines().find(p=>p.id===S.pipelineId)}
function reviewPage(){return !!S.plan&&!S.reviewPanel}
function cohort(){return projectCohorts().find(c=>c.id===S.cohortId)}
function selectedStage(){return pipeline()?.stages.find(s=>s.id===S.stageId)}
function dirtyWarning(){return S.dirty?'<div class="warning" role="status">You have unsaved edits. Save before reviewing or running this study.</div>':''}
function phaseOutput(p,s){if(s.kind==='poll')return Object.entries(s.questions||{}).map(([id,q])=>({id,label:q.label,type:q.type}));return [{id:s.outputQuestion,label:s.label,type:resolvedQuestion(p,s.id,s.outputQuestion)?.type||'result'}]}
function resolvedQuestion(p,stageId,questionId,seen=new Set()){if(seen.has(stageId))return null;seen.add(stageId);const s=p.stages.find(x=>x.id===stageId);if(!s)return null;if(s.kind==='poll')return s.questions[questionId];const from=s.kind==='decision'?s.from:s.inputs?.[0];return from?resolvedQuestion(p,from.stage,from.question,seen):null}
function poolForPhase(p,s){return S.doc.cohorts.find(c=>c.id===p.cohorts[s.cohort])}
function stageMap(p){return flowCanvas(p)}
function studyList(){const page=pageItems(projectPipelines(),'pipelines',viewportPageSize(6,3));const items=page.items.map(p=>{const count=new Set(Object.values(p.cohorts).filter(cid=>S.doc.cohorts.some(c=>c.id===cid))).size;return listRow('open-pipeline',p,'Open study: '+studyQuestion(p),studyQuestion(p),'',[p.stages.length+' '+(p.stages.length===1?'step':'steps'),count+' '+(count===1?'cohort':'cohorts')],studyDeleteButton(p),'study-list-item')}).join('');return items?'<div class="list">'+items+'</div>'+page.controls:empty('A clean research bench','Start with the decision your study should inform. Then define cohorts and steps; nothing runs until you review it.')}
function runTitle(r){const p=S.doc?.pipelines.find(x=>x.id===r.pipelineId);return p?studyQuestion(p):(r.pipelineName||'Study run')}
function studyQuestion(p){return p.description?.trim()||(typeof p.context?.decisionQuestion==='string'&&p.context.decisionQuestion.trim())||p.name||'Untitled study'}
function studies(){
  const p=pipeline();
  if(!p){
    const listing=projectPipelines().length>0;
    const content=listing?studyList():emptyCreate('create-study','New study','Click anywhere here to start. You name it with the question it should answer, then add rounds on its track.');
    return header('Studies',esc(project()?.description?.trim()||'Each study asks one or more cohorts a chain of questions.'),(S.dirty?saveButton():'')+(listing?'<button class="button primary" data-act="create-study">'+icon('plus')+'New study</button>':''))+tabs()+'<section id="view-studies" role="tabpanel" aria-labelledby="tab-studies">'+content+'</section>';
  }
  const s=selectedStage(),mode=S.sections.pipeline||'flow';const edit=mode==='phase'&&S.sections['question-list-'+p.id]?studyQuestionList(p):s?stageForm(p,s):empty('Add your first question','Choose who answers, then define their answer options.','<button class="button primary" data-act="add-stage" data-kind="poll">Add first question</button>');
  const navigation='';
  const heading='<header class="study-workspace-header">'+(mode==='advanced'&&s?'<div class="study-title"><h1 tabindex="-1">'+esc(stepSettingsTitle(p,s))+'</h1></div>':mode==='context'?'<div class="study-title"><h1 tabindex="-1">Study settings</h1></div>':studyTitle(p))+'<div class="study-header-actions">'+saveButton()+((mode==='phase'&&s?.kind==='poll')?'':'<button class="button" data-act="draft-panel-open">Draft with assistant</button>'+studyNextButtons(p))+'</div></header>';
  return heading+'<section id="view-studies" aria-label="Study editor">'+navigation+(mode==='flow'?flowWorkspace(p,s):mode==='context'?pipelineForm(p):edit)+'</section>'}

function pipelineForm(p){return panel('Study brief','Name the decision, context, and synthetic panels this study may use.','<form data-form="pipeline" class="grid2">'+area('Research question','description',p.description,'Names the study everywhere in the workspace.','2')+field('Study name','name',p.name,'text','Used in exported files, reports and the CLI.')+area('Shared context · JSON','context',JSON.stringify(p.context??{},null,2),'Known facts and assumptions for the model. Keep evidence and assumptions distinct.','5')+'<div class="field"><span class="field-label">Available cohorts</span><div class="row">'+Object.entries(p.cohorts).map(([alias,cid])=>'<span class="seg-pill">'+esc(alias)+' → '+esc(S.doc.cohorts.find(c=>c.id===cid)?.name||'Choose a cohort')+' <button type="button" data-act="remove-alias" data-alias="'+attr(alias)+'" aria-label="Remove '+attr(alias)+' panel alias">×</button></span>').join('')+'</div><small>Aliases are selected in each poll step. Add one to make a cohort available.</small></div><div class="grid2">'+field('Cohort alias','cohortAlias',Object.keys(p.cohorts)[0]||'audience')+select('cohortId',[{value:'',label:'Choose a saved cohort'},...projectCohorts().map(c=>({value:c.id,label:c.name}))],p.cohorts[Object.keys(p.cohorts)[0]||'']||'','Cohort to assign')+'</div><div class="row"><button class="button soft" type="submit">Apply brief</button></div></form>')}
function freshCondition(p,s){const st=p.stages.find(x=>x.id!==s.id);const q=st?.kind==='poll'?Object.keys(st.questions)[0]:st?.outputQuestion||'';return {stage:st?.id||'',question:q,metric:'topProbability',op:'gte',value:.5}}
function conditionNodeHtml(c,p,s,path='root'){const kind=c?.all?'all':c?.any?'any':c?.not?'not':'leaf',leaf=kind==='leaf'?c:freshCondition(p,s),options=p.stages.filter(x=>x.id!==s.id).map(x=>({value:x.id,label:stepTitle(p,x)+' · '+x.kind})),children=kind==='all'?c.all:kind==='any'?c.any:kind==='not'?[c.not]:[];const leafHtml='<div class="grid2"><div class="field"><label>Result step</label><select aria-label="Result step" data-cond-field="stage" name="cond-stage-'+path+'">'+options.map(o=>'<option value="'+attr(o.value)+'" '+(leaf.stage===o.value?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></div><div class="field"><label>Question</label><select aria-label="Question" data-cond-field="question" name="cond-question-'+path+'">'+questionOptions(p,leaf.stage).map(o=>'<option value="'+attr(o.value)+'" '+(leaf.question===o.value?'selected':'')+'>'+esc(o.label)+'</option>').join('')+'</select></div><div class="field"><label>Measure</label><select aria-label="Measure" data-cond-field="metric" name="cond-metric-'+path+'">'+[{value:'winner',label:'Winning option'},{value:'topProbability',label:'Top probability'},{value:'margin',label:'Lead margin'},{value:'mean',label:'Mean score'}].map(o=>'<option value="'+o.value+'" '+(leaf.metric===o.value?'selected':'')+'>'+o.label+'</option>').join('')+'</select></div><div class="field"><label>Rule</label><select aria-label="Rule" data-cond-field="op" name="cond-op-'+path+'">'+[{value:'gt',label:'Greater than'},{value:'gte',label:'At least'},{value:'lt',label:'Less than'},{value:'lte',label:'At most'},{value:'eq',label:'Equals'},{value:'ne',label:'Does not equal'}].map(o=>'<option value="'+o.value+'" '+(leaf.op===o.value?'selected':'')+'>'+o.label+'</option>').join('')+'</select></div><div class="field"><label>Threshold or option</label><input aria-label="Threshold or option" data-cond-field="value" name="cond-value-'+path+'" value="'+attr(leaf.value??.5)+'"></div></div>';const childrenHtml=children.map((child,i)=>conditionNodeHtml(child,p,s,path+'.'+i)).join('');return '<div class="condition-node" data-cond-path="'+path+'" data-cond-type="'+kind+'"><div class="row"><strong>'+({'root':'Condition','all':'All of these','any':'Any of these','not':'Not this rule','leaf':'Rule'}[kind])+'</strong><select aria-label="Condition structure" data-cond-kind="'+path+'" name="cond-kind-'+path+'"><option value="leaf" '+(kind==='leaf'?'selected':'')+'>Single rule</option><option value="all" '+(kind==='all'?'selected':'')+'>All rules</option><option value="any" '+(kind==='any'?'selected':'')+'>Any rule</option><option value="not" '+(kind==='not'?'selected':'')+'>Not a rule</option></select>'+(path!=='root'?'<button type="button" class="button small danger" data-act="condition-remove" data-path="'+path+'">Remove</button>':'')+'</div>'+(kind==='leaf'?leafHtml:childrenHtml)+(kind==='all'||kind==='any'?'<button type="button" class="button small" data-act="condition-add" data-path="'+path+'">＋ Add nested rule</button>':'')+'</div>'}
function conditionForm(s,p){return '<label class="checkrow"><input name="hasWhen" type="checkbox" '+(s.when?'checked':'')+'> Run only when a condition matches</label><div data-condition-editor '+(s.when?'':'hidden')+'>'+conditionNodeHtml(s.when||freshCondition(p,s),p,s)+'</div><p class="subtle">Combine all, any, not, and leaf rules to describe explicit branches.</p>'}
function questionOptions(p,stageId){const st=p.stages.find(x=>x.id===stageId);if(!st)return[{value:'',label:'Choose a step first'}];if(st.kind==='poll')return Object.keys(st.questions).map(q=>({value:q,label:q}));return [{value:st.outputQuestion,label:st.outputQuestion}];}
function dataInputOptions(p,s){return p.stages.filter(x=>x.id!==s.id&&!dependsOnPhase(p,x.id,s.id))}
function dependsOnPhase(p,stageId,target,seen=new Set()){if(seen.has(stageId))return false;seen.add(stageId);const stage=p.stages.find(x=>x.id===stageId);return (stage?.dependsOn||[]).some(id=>id===target||dependsOnPhase(p,id,target,seen))}
function projectionOptions(p,input){const type=resolvedQuestion(p,input.stage,input.question)?.type;return [{value:'summary',label:'Full summary'},{value:'responses',label:'Individual responses'},...(type==='choice'?[{value:'winner',label:'Winning option'}]:[]),...(type==='noul'||type==='score'?[{value:'mean',label:'Mean value'}]:[]),...(type==='choice'||type==='score'?[{value:'probabilities',label:'Probability distribution'}]:[])]}
function phaseInputsEditor(p,s){const inputs=Object.entries(s.inputs||{}),available=dataInputOptions(p,s);return '<div class="toolbar"><strong>Inputs from earlier steps</strong><button type="button" class="button small" data-act="add-phase-input" '+(!available.length?'disabled':'')+'>＋ Connect output</button></div>'+(s.inputs===undefined&&s.dependsOn.length?'<p class="subtle">This saved step receives all completed dependency summaries. Add a named input to control the exact output passed to Jev.</p>':'')+(inputs.length?inputs.map(([name,input],i)=>'<div class="phase-input" data-phase-input="'+i+'"><div class="grid2">'+field('Input name','bindingName'+i,name,'text','Available to the question as inputs.'+name,'',String(i))+select('bindingStage'+i,available.map(x=>({value:x.id,label:stepTitle(p,x)})),input.stage,'Source step',String(i))+select('bindingQuestion'+i,questionOptions(p,input.stage),input.question,'Source output',String(i))+select('bindingSelect'+i,projectionOptions(p,input),input.select||'summary','Pass through',String(i))+'</div><div class="input-row-actions"><code>inputs.'+esc(name)+'</code><button type="button" class="button small danger" data-act="remove-phase-input" data-name="'+attr(name)+'">Disconnect input</button></div></div>').join(''):'<p class="subtle">'+(available.length?'No connected outputs. This step uses its cohort and shared context.':'First step: input is your cohort and shared context.')+'</p>')}
function advancedStageForm(p,s){
  const modeKey='step-settings-'+p.id+'-'+s.id,modeTabs=sectionTabs(modeKey,[{id:'simple',label:'Simple'},{id:'advanced',label:'Advanced'}]);
  const picker='<div class="phase-picker">'+select('phasePicker',p.stages.map(x=>({value:x.id,label:stepTitle(p,x)})),s.id,'Selected step')+'</div>';
  const remove='<div class="sticky-actions"><button class="button danger" type="button" data-act="delete-stage" data-id="'+attr(s.id)+'">Remove step</button></div>';
  if(S.sections[modeKey]!=='advanced'){
    const configured=[s.repeats>1?s.repeats+' evaluations per persona':'',Object.keys(s.context||{}).length?'Extra context':'',s.dependsOn.length?'Dependencies':'',s.when?'Branch condition':'',s.kind==='poll'&&Object.keys(s.inputs||{}).length?'Earlier results':''].filter(Boolean);
    const basics=field('Step name','label',s.label)+(s.kind==='poll'?field('Personas to consult','size',s.size??'','number','Leave blank to use everyone in the selected cohort.','min="1"'):''),summary=s.kind==='poll'?'The question, cohort and answer options are edited on the step itself.':s.kind==='aggregate'?'Combines earlier results. Configure source outputs and their weights in Advanced.':'Uses an earlier result. Choose its source and output in Advanced.';
    const content='<form data-form="stage" data-settings-mode="simple" class="phase-form-tabs">'+modeTabs+'<div class="step-settings-simple">'+(s.kind==='poll'&&setupQuestion(s)?setupTypeChooser(setupQuestion(s)[1]):'')+'<p class="subtle">'+summary+'</p><div class="grid2">'+basics+'</div>'+(configured.length?'<p class="subtle">Active advanced settings: '+esc(configured.join(' · '))+'. Switching modes keeps these settings.</p>':'<p class="subtle">Use Advanced for execution rules, custom instructions, and output settings.</p>')+'</div>'+remove+'</form>';
    return panel('Step settings','',content,picker);
  }
  const depOpts=p.stages.filter(x=>x.id!==s.id).map(x=>({value:x.id,label:stepTitle(p,x)+' · '+x.kind}));
  const dependencies='<div class="grid2">'+select('join',[{value:'all',label:'All dependencies must complete'},{value:'any',label:'Any dependency can continue'}],s.join||'all','Dependency rule')+'<div class="field"><label>Requires</label><div class="condition">'+depOpts.map(o=>'<label class="checkrow"><input type="checkbox" name="dependsOn" value="'+attr(o.value)+'" '+(s.dependsOn.includes(o.value)?'checked':'')+'> '+esc(o.label)+'</label>').join('')+(depOpts.length?'':'<small>No other steps yet.</small>')+'</div></div></div>';
  let sections,singleQuestion=false,basics='';
  if(s.kind==='poll'){
    const entries=Object.entries(s.questions),questions=entries.map(([qid,q])=>({id:qid,label:q.label||qid,html:questionEditor(qid,q)}));singleQuestion=entries.length===1;const parts=singleQuestion?questionParts(entries[0][0],entries[0][1]):[];
    const instructions=singleQuestion?'<input type="hidden" name="questionLabel" value="'+attr(entries[0][1].label)+'">'+area('Additional instructions','questionInstructions',entries[0][1].instructions,'Special guidance for this question. Its text, cohort, and answer options live under Questions.','3',entries[0][0]):questions.length?sectionPanels('questions-'+s.id,questions):'<p>Add a question under Execution.</p>';
    sections=[
      {id:'rules',label:'Execution',html:'<div class="grid2">'+field('Step name','label',s.label)+field('Personas to consult','size',s.size??'','number','Blank uses the entire cohort.','min="1"')+field('Repeated evaluations','repeats',s.repeats??1,'number','Repeats do not add people.','min="1"')+area('Step context · JSON','stageContext',JSON.stringify(s.context??{},null,2),'Extra context supplied to each Jev.','3')+'</div>'+dependencies+conditionWrap(s,p)+'<button type="button" class="button small" data-act="add-question">Add another question to this step</button>'},
      {id:'inputs',label:'Earlier results',html:phaseInputsEditor(p,s)},
      {id:'instructions',label:singleQuestion?'Instructions':'Question definitions',html:instructions},
      ...(singleQuestion?[{id:'answer',label:'Output contract',html:parts[1].html}]:[])
    ];
  }else{
    const inputs=s.kind==='aggregate'?'<div class="field"><label>Inputs to combine</label>'+s.inputs.map((input,i)=>'<div class="item-card"><div class="grid3">'+select('inputStage'+i,p.stages.filter(x=>x.id!==s.id).map(x=>({value:x.id,label:stepTitle(p,x)})),input.stage,'Source step')+select('inputQuestion'+i,questionOptions(p,input.stage),input.question,'Output')+field('Weight','inputWeight'+i,input.weight,'number','Relative step weight.','min="0" step="any"')+'</div><button type="button" class="button small danger" data-act="remove-input" data-index="'+i+'">Remove input</button></div>').join('')+'<button type="button" class="button small" data-act="add-input">＋ Add input</button></div>':'<div class="grid2">'+select('fromStage',p.stages.filter(x=>x.id!==s.id).map(x=>({value:x.id,label:stepTitle(p,x)})),s.from.stage,'Source step')+select('fromQuestion',questionOptions(p,s.from.stage),s.from.question,'Source output')+'</div>';
    sections=[{id:'inputs',label:'Inputs & output',html:field('Step name','label',s.label)+inputs+field('Output name','outputQuestion',s.outputQuestion)},{id:'rules',label:'Rules',html:dependencies+conditionWrap(s,p)}];
  }
  const content='<form data-form="stage" class="phase-form-tabs">'+modeTabs+basics+(singleQuestion?'<div class="question-card question-flat">':'')+sectionPanels('phase-'+s.id,sections)+(singleQuestion?'</div>':'')+remove+'</form>';
  return panel('Step settings',s.kind==='decision'?'Uses an earlier result. Add a cohort step to ask another question.':'',content,picker);
}
function conditionWrap(s,p){return '<div class="field"><label>Branch condition</label><div class="condition">'+conditionForm(s,p)+'</div></div>'}
function questionEditor(qid,q){return '<div class="question-card">'+sectionPanels('question-'+qid,questionParts(qid,q))+'</div>'}
function questionParts(qid,q){
  const details=q.type==='choice'?area('Option definitions (JSON)','criteria',JSON.stringify(q.criteria,null,2),'Stable keys map to descriptions, or objects with label and description. Use Question & cohort for visual editing.','5',qid):q.type==='score'?area('Ordered score levels · one description per line','criteria',q.criteria.join('\n'),'Describe concrete, ordered states; Score rubrics use 2–10 ordered levels.','3',qid):'<p class="subtle">Yes/no judgment. Use instructions to define what “yes” means.</p>';
  return [
    {id:'prompt',label:'Prompt',html:field('What should this cohort decide?','questionLabel',q.label,'text','','',qid)+area('Instructions','questionInstructions',q.instructions,'Complete meaning is sent with each poll.','3',qid)},
    {id:'answer',label:'Answer & output',html:'<div class="grid2">'+field('Output name','questionId',qid,'text','','',qid)+select('questionType',[{value:'choice',label:'Choice'},{value:'score',label:'Score'},{value:'noul',label:'Yes / no'}],q.type,'Answer type',qid)+'</div>'+details+'<button type="button" class="button small danger" data-act="remove-question" data-id="'+attr(qid)+'">Remove question</button>'}
  ];
}

const segmentColors=['#58748c','#727aaf','#b5813f','#957399','#888888'];
function poolComposition(c){const total=c.segments.reduce((n,s)=>n+Math.max(0,s.weight),0);return '<div class="composition" role="img" aria-label="'+attr(c.segments.map(s=>s.label+': '+(total?Math.round(100*s.weight/total):0)+' percent').join(', '))+'">'+c.segments.map((s,i)=>'<span style="--segment-color:'+segmentColors[i%segmentColors.length]+';--segment-share:'+Math.max(0,s.weight)+'"></span>').join('')+'</div><div class="segment-legend">'+c.segments.map((s,i)=>'<span style="--segment-color:'+segmentColors[i%segmentColors.length]+'">'+esc(s.label)+' '+(total?Math.round(100*s.weight/total):0)+'%</span>').join('')+'</div>'}
function poolCloud(c){return '<div class="pool-cloud" aria-hidden="true">'+c.personas.slice(0,90).map(p=>'<span style="--segment-color:'+segmentColors[Math.max(0,c.segments.findIndex(s=>s.id===p.segment))%segmentColors.length]+'"></span>').join('')+'</div>'}

function showingLocalJob(){return !!project()&&(cohortJobNoticeVisible()||commandJobVisible()||S.tab==='agents'||inlineCohortJobVisible()||(S.tab==='cohorts'&&(S.cohortComposer||S.personaOpen&&S.personaRegenOpen)))}
function draftReady(){return S.localEngines?.some(e=>e.id===S.localEngine&&e.available)&&(S.localEngine!=='chatgpt'||(!!S.chatgptModel.trim()&&S.chatgptModel.length<=200&&!S.chatgptLoading&&!S.chatgpt?.signingIn))}
function chatGptControlsBody(){
  if(S.localEngine!=='chatgpt')return '';
  const c=S.chatgpt,busy=S.chatgptLoading||S.localJob?.status==='running';
  const model=c?.connected&&c.planEnabled?select('chatgptModel',[{value:'',label:'Choose a model'},...S.chatgptModels.map(m=>({value:m.id,label:m.name})),{value:'__custom__',label:'Enter model ID…'}],S.chatgptCustomModel?'__custom__':S.chatgptModel,'Drafting model')+(S.chatgptCustomModel?field('Model ID','chatgptCustomModelId',S.chatgptModel,'text','Enter an exact model ID. Access is checked when you generate.','maxlength="200" placeholder="gpt-6.1-sol" autocomplete="off" spellcheck="false"'):''):'';
  const account=(c?.accounts?.length>1?select('chatgptAccount',c.accounts.map(a=>({value:a.id,label:a.label})),c.account?.id||'','ChatGPT account').replace('<select ', '<select '+(busy?'disabled ':'')):'')+(c?.signingIn?'<p role="status">Finish sign-in in the browser window.</p><button type="button" class="button" data-act="chatgpt-cancel">Cancel sign-in</button>':'<div class="toolbar"><button type="button" class="button" data-act="chatgpt-connect" '+(busy?'disabled':'')+'>'+(c?.connected?'Reconnect ChatGPT':'Continue with ChatGPT')+'</button>'+(c?.connected?'<button type="button" class="button" data-act="chatgpt-add" '+(busy?'disabled':'')+'>Add account</button><button type="button" class="button" data-act="chatgpt-disconnect" '+(busy?'disabled':'')+'>Disconnect</button>':'')+'</div>')+'<div class="toolbar"><a class="button" href="https://chatgpt.com/settings/usage" target="_blank" rel="noopener noreferrer">Manage ChatGPT access and usage <span aria-hidden="true">↗</span></a></div>';
  return '<section aria-label="ChatGPT connection">'+model+(c?.account?'<p class="subtle ai-status">ChatGPT plan · '+esc(c.account.label)+'</p>':'')+'<div class="connection-extra">'+account+'</div>'+(c?.connected&&!c.planEnabled?'<p class="warning">Plan usage is not enabled. Reconnect to grant permission.</p>':'')+(c?.message&&(!c.connected||!c.planEnabled||c.signingIn)?'<p role="status">'+esc(c.message)+'</p>':'')+(S.chatgptError?'<p class="warning" role="alert">'+esc(S.chatgptError)+'</p>':'')+'</section>';
}

let chatgptPoll=false;
async function loadChatGpt(){
  if(S.chatgptLoading)return;S.chatgptLoading=true;S.chatgptError=null;
  try{
    const accountId=S.chatgpt?.account?.id;S.chatgpt=await api('/api/chatgpt/status');
    if(accountId!==S.chatgpt.account?.id){S.chatgptModel='';S.chatgptCustomModel=false;restoreAIModel()}
    if(S.chatgpt.connected&&S.chatgpt.planEnabled&&!S.chatgpt.signingIn){
      try{const catalog=await api('/api/chatgpt/models');if(!Array.isArray(catalog.models))throw Error('Could not load the model catalog. Enter a model ID or try again.');S.chatgptModels=catalog.models;if(!S.chatgptCustomModel&&!S.chatgptModels.some(m=>m.id===S.chatgptModel))S.chatgptModel=''}
      catch(error){S.chatgptError=error.message;S.chatgptModels=[];if(!S.chatgptCustomModel)S.chatgptModel=''}
    }else{S.chatgptModels=[];S.chatgptModel='';S.chatgptCustomModel=false}
  }catch(error){S.chatgptError=error.message;S.chatgptModels=[];S.chatgptModel='';S.chatgptCustomModel=false}
  finally{S.chatgptLoading=false;updateAISettings();updateDraftReadiness()}
  if(S.chatgpt?.signingIn)void pollChatGpt()
}
async function pollChatGpt(){if(chatgptPoll)return;chatgptPoll=true;try{while(S.chatgpt?.signingIn){await new Promise(resolve=>setTimeout(resolve,1000));await loadChatGpt()}await loadLocalAgents()}finally{chatgptPoll=false}}
async function changeChatGpt(action,accountId){if(S.chatgptLoading)return;S.chatgptLoading=true;try{await api('/api/chatgpt/'+action,'POST',accountId?{accountId}:{});S.chatgptModel='';S.chatgptCustomModel=false}finally{S.chatgptLoading=false}await loadChatGpt();await loadLocalAgents()}
function cohortBlockReason(){
  if(S.localStarting||S.localJob?.status==='running')return '';
  if(S.remoteRevision!==null)return 'Reload the saved workspace before generating; another session changed it.';
  if(!Number.isInteger(S.cohortSize)||S.cohortSize<1||S.cohortSize>COHORT_MAX)return 'Enter a whole number from 1 to '+COHORT_MAX.toLocaleString('en-US')+' personas.';
  if(!S.cohortPrompt.trim())return 'Describe who should be in this cohort.';
  if(S.cohortPrompt.trim().length>10000)return 'Keep the cohort prompt under 10,000 characters.';
  if(S.localLoading||S.chatgptLoading&&S.localEngine==='chatgpt')return 'Checking your drafting connection…';
  if(!S.localEngines?.some(e=>e.id===S.localEngine&&e.available))return 'Choose an available provider in AI settings above.';
  if(S.localEngine==='chatgpt'&&S.chatgpt?.signingIn)return 'Finish ChatGPT sign-in before generating.';
  if(!draftReady())return 'Choose a drafting model or enter its model ID in AI settings above.';
  return '';
}
function canGenerateCohort(){return !S.localStarting&&S.localJob?.status!=='running'&&!cohortBlockReason()}
function cohortCountInput(el,finish=false){
  if(el.value===''&&!finish){S.cohortSize=NaN;updateDraftReadiness();return}
  const next=Number(el.value);
  if(!Number.isInteger(next)||next<1||next>COHORT_MAX){
    el.value=String(Number.isInteger(S.cohortSize)&&S.cohortSize>=1&&S.cohortSize<=COHORT_MAX?S.cohortSize:S.cohortLastSize);
    S.cohortSize=Number(el.value);say('Use a whole number from 1 to '+COHORT_MAX.toLocaleString('en-US')+'. Kept '+plural(Number(el.value),'persona')+'.');
  }else{S.cohortSize=next;S.cohortLastSize=next}
  updateDraftReadiness();
}
function updateDraftReadiness(){
  const cohortButton=root.querySelector('[data-act=cohort-generate],[data-act=flow-audience-generate]');if(cohortButton)cohortButton.disabled=!canGenerateCohort()||cohortButton.dataset.act==='flow-audience-generate'&&cohortDraftElsewhere(pipeline(),selectedStage());
  const reason=document.getElementById('cohortReadiness');if(reason){reason.textContent=cohortBlockReason();reason.hidden=!reason.textContent}
  optionAgentUpdate();const personaButton=root.querySelector('[data-act=persona-regenerate]');if(personaButton)personaButton.disabled=S.remoteRevision!==null||S.localLoading||S.localJob?.status==='running'||!draftReady();const assistantButton=root.querySelector('[data-act=assistant-generate]');if(assistantButton)assistantButton.disabled=!draftReady()||!S.localPrompt.trim()||S.remoteRevision!==null||S.localJob?.status==='running'||S.localLoading;
}
function inlineCohortJobVisible(){
  const p=pipeline(),s=selectedStage();if(S.tab!=='studies'||S.plan||!inlineCohortTarget(p,s))return false;
  const mode=S.sections.pipeline||'flow';if(mode==='flow')return S.sections['flow-inspector']==='cohort';
  return mode==='phase'&&!S.sections['question-list-'+p.id]&&S.sections[setupWizardKey(p,s,setupQuestion(s)?.[0])]==='cohort';
}
function inlineCohortTarget(p,s){return !!(S.cohortComposer&&p&&s&&S.cohortInlineTarget?.pipelineId===p.id&&S.cohortInlineTarget?.stageId===s.id)}
function cohortDraftElsewhere(p,s){return !!(S.localJob?.cohort&&['running','completed'].includes(S.localJob.status)&&(!S.cohortInlineTarget||S.cohortInlineTarget.pipelineId!==p?.id||S.cohortInlineTarget.stageId!==s?.id))}
function openCohortGenerator(target){
  const inline=S.tab==='studies'&&selectedStage()?.kind==='poll';
  if(inline){
    if(cohortDraftElsewhere(pipeline(),selectedStage())){say('Review or discard the existing cohort draft before creating another.');render();return}
    if(S.localJob?.cohort&&['cancelled','failed'].includes(S.localJob.status)&&(S.cohortInlineTarget?.pipelineId!==S.pipelineId||S.cohortInlineTarget?.stageId!==S.stageId)){S.localJob=null;S.cohortTarget=null;S.cohortPrompt='';rememberLocalJob(null)}
    if(!S.localJob?.cohort&&(S.cohortInlineTarget?.pipelineId!==S.pipelineId||S.cohortInlineTarget?.stageId!==S.stageId)){S.cohortTarget=null;S.cohortPrompt='';S.cohortSize=8}
    S.cohortInlineTarget={pipelineId:S.pipelineId,stageId:S.stageId};
    S.sections['flow-inspector']='cohort';S.flowCohortPick=true;
  }else{S.tab='cohorts';if(!S.localJob?.cohort)S.cohortInlineTarget=null}
  S.cohortComposer=true;S.sections['cohort-generation']=S.localJob?.cohort?'review':'prompt';S.localError=null;
  if(target){S.cohortTarget=target.id;S.cohortPrompt=target.generationPrompt||target.population||'';S.cohortSize=Math.min(COHORT_MAX,Math.max(1,target.personas.length||8))}
  else if(S.localJob?.cohort&&!S.proposalApplied){S.cohortTarget=S.localJob.cohort.id;S.cohortPrompt=S.localJob.cohort.prompt;S.cohortSize=S.localJob.cohort.size}
  else if(S.proposalApplied||!S.cohortPrompt){S.cohortTarget=null;S.cohortPrompt='';S.cohortSize=8}
  S.cohortLastSize=S.cohortSize;render();void loadLocalAgents();
}
function cohortGenerator(inline=false){
  const returnToStudy=!cohort()&&projectPipelines().some(p=>p.id===S.cohortReturn?.pipelineId);
  const active=S.localStart||S.localJob,job=active?.cohort&&(!S.cohortTarget||active.cohort.id===S.cohortTarget)?active:null,running=!!S.localStart||S.localJob?.status==='running',target=S.doc.cohorts.find(c=>c.id===S.cohortTarget);
  const form='<'+(inline?'div':'form')+' data-form="cohort-generator"><fieldset '+(running?'disabled':'')+' style="border:0;padding:0;margin:0;min-width:0">'+area(inline?'Who are they?':'Who should be in this cohort?','cohortPrompt',S.cohortPrompt,'Describe their context, habits, and relevant differences. A few sentences are enough.','4')+field(inline?'How many people?':'Number of personas','cohortSize',S.cohortSize,'number','Up to '+COHORT_MAX.toLocaleString('en-US')+' personas per cohort. Larger cohorts generate in batches.','min="1" max="'+COHORT_MAX+'" step="1"')+(target?'<p class="subtle">Proposes a replacement for '+esc(target.name)+'. Your current cohort stays saved until you accept and save the new draft.</p>':'')+'</fieldset><div class="row generation-actions"><button class="button primary" type="button" data-act="cohort-generate" aria-describedby="cohortReadiness" '+(!canGenerateCohort()?'disabled':'')+'>'+(running?'Generating personas…':job?.status==='completed'?'Generate another version':inline?'Generate':'Generate cohort')+'</button>'+draftCancelButton(active)+'</div><p id="cohortReadiness" class="warning" role="status" '+(!cohortBlockReason()?'hidden':'')+'>'+esc(cohortBlockReason())+'</p></'+(inline?'div':'form')+'>'+(S.localError?'<p class="warning" role="alert">'+esc(S.localError)+'</p>':'');
  return (inline?'<div class="setup-section-heading"><h3>Create the audience</h3><button type="button" class="button small" data-act="cohort-generator-close">Back to who answers</button></div>':focusedHeader(target?'Regenerate personas':'New cohort','Describe who belongs in it. AI drafts the personas; you decide what to keep.',target?'Regenerate personas':'New cohort',returnToStudy?'back-cohort-pipeline':'cohort-generator-close',returnToStudy?'Back to study':cohort()?'Back to cohort':'Back to cohorts'))+'<section id="view-cohort-generator" class="generation-workspace" aria-label="Cohort generation">'+sectionPanels('cohort-generation',[{id:'prompt',label:'Cohort prompt',html:panel('Cohort prompt','Generate a varied group of virtual people from your description.',form)},...(target?.distributionTargets?.length?[{id:'targets',label:'Targets',html:panel('Generation targets','',targetOverview(target,target.distributionTargets,true))}]:[]),...(job||running?[{id:'review',label:running?'Progress':'Review draft',html:job?cohortProposalReview(job):proposalReview(active)}]:[])])+'<p class="subtle generation-note">Current edits save automatically when you generate. Generated personas stay separate until review.</p><details class="generation-help"><summary>About generation</summary><p class="subtle">Generated profiles are synthetic assumptions, not observations about real people. Include source facts in your brief when available. Review and edit the proposed personas before saving the cohort.</p></details>'+(inline?'':'<div class="toolbar"><button class="button small" data-act="manual-cohort">Create manually</button></div>')+'</section>';

}
function cohortProposalReview(job){
  if(job.status==='running')return draftProgress(job);
  if(job.status!=='completed'||!job.proposal)return panel(job.status==='cancelled'?'Generation cancelled':'Generation failed','', '<p class="warning">'+esc(job.message)+'</p>');
  const c=job.proposal.document.cohorts.find(c=>c.id===job.cohort.id);if(!c)return '';
  const stale=S.revision!==job.revision||S.remoteRevision!==null;
  const page=pageItems(c.personas,'proposal-'+job.id,viewportPageSize(3,1));const people=page.items.map(p=>'<details class="review-persona"><summary><strong>'+esc(p.label)+'</strong><span>'+esc(c.segments.find(s=>s.id===p.segment)?.label||p.segment)+' · age '+p.age+'</span></summary><p>'+esc(p.background)+'</p><dl>'+Object.entries(p.attributes).map(([key,value])=>'<dt>'+esc(key)+'</dt><dd>'+esc(typeof value==='string'?value:JSON.stringify(value))+'</dd>').join('')+'</dl><p class="subtle">Weight '+p.weight+' · Synthetic: '+esc(p.syntheticFields.join(', '))+'</p></details>').join('');
  const decide='<div class="toolbar"><button class="button primary" data-act="cohort-adopt" '+(stale||S.dirty?'disabled':'')+'>'+(S.cohortInlineTarget?'Use this audience':'Review and edit cohort')+'</button><button class="button" data-act="assistant-discard">Discard version</button></div><p class="subtle">'+(S.cohortInlineTarget?'Adds this reviewed audience to the step. Save when ready; no study starts.':'Opens an editable draft. Save it when you are ready; no study starts.')+'</p>';
  return panel('Review generated cohort',plural(c.personas.length,'persona')+' · '+plural(c.segments.length,'segment'),'<h3>'+esc(c.name)+'</h3><p>'+esc(c.population)+'</p><p class="subtle">'+esc(job.proposal.explanation)+'</p>'+(S.cohortInlineTarget?decide:'')+poolComposition(c)+'<div class="cohort-review-grid">'+people+'</div>'+page.controls+(c.assumptions.length?'<details class="advanced"><summary>Assumptions</summary><ul>'+c.assumptions.map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul></details>':'')+(stale?'<p class="warning">Workspace changed. Generate again using the latest saved revision.</p>':'')+(S.cohortInlineTarget?'':decide));
}
async function startCohortJob(){
  if(!project())throw Error('Open a project first.');
  if(S.localStarting||S.localJob?.status==='running'||S.localLoading)return;
  if(!canGenerateCohort())throw Error(cohortBlockReason());
  await startDraftJob(()=>{S.cohortTarget=S.cohortTarget||id();S.sections['cohort-generation']='review';S.cohortComposer=true;return {prompt:S.cohortPrompt.trim(),cohort:{id:S.cohortTarget,size:S.cohortSize}}});
}

function adoptCohortProposal(){
  const job=S.localJob;if(job?.projectId&&job.projectId!==S.projectId)throw Error('Open the project that generated this draft.');if(job?.status!=='completed'||!job.cohort||!job.proposal)return;
  if(S.dirty||S.revision!==job.revision||S.remoteRevision!==null)throw Error('Workspace changed. Save your edits and generate a new cohort.');
  const proposed=job.proposal.document.cohorts.find(c=>c.id===job.cohort.id);if(!proposed)throw Error('Generated cohort is missing. Try again.');const c=clone(proposed);
  const index=S.doc.cohorts.findIndex(x=>x.id===c.id);if(index<0)S.doc.cohorts.push(c);else S.doc.cohorts[index]=c;ownCohort(c);
  const destination=S.cohortInlineTarget,p=destination&&projectPipelines().find(p=>p.id===destination.pipelineId),stage=p?.stages.find(s=>s.id===destination.stageId&&s.kind==='poll');
  S.cohortId=c.id;S.personId=null;resetExplorer();S.cohortComposer=false;if(stage){assignSetupCohort(p,stage,c.id);S.tab='studies';S.plan=null;S.pipelineId=p.id;S.stageId=stage.id;S.sections.pipeline='flow';S.sections['flow-inspector']='cohort';S.flowCohortPick=false;S.flowPanel=true}else if(!destination)S.tab='cohorts';S.cohortInlineTarget=null;S.dirty=true;S.plan=null;S.proposalApplied=true;settleLocalJob(job.id);S.localJob=null;rememberLocalJob(null);render();say(stage?'Audience assigned to this step and added to your library. Save changes when ready.':destination?'Cohort added to the library. The original step no longer exists.':'Review and edit your cohort, then save changes.');
}

function requestCohortDeletion(cohortId){
  const target=S.doc.cohorts.find(c=>c.id===cohortId);if(!target)return;
  S.cohortDeletion={id:cohortId,revision:S.revision};
  const used=S.doc.pipelines.filter(p=>Object.values(p.cohorts).includes(cohortId));
  document.getElementById('deleteCohortDescription').textContent='Remove “'+target.name+'” and its '+target.personas.length+' persona'+(target.personas.length===1?'':'s')+' from this draft? Save changes afterward to keep the deletion. Past reports stay unchanged.';
  document.getElementById('deleteCohortUsage').textContent=used.length?'Used by: '+used.map(p=>p.name).join(', ')+'. These cohort connections will be removed. Select another cohort in affected steps before running.':'No studies use this cohort.';
  document.getElementById('deleteCohortDialog').showModal();
}
function deleteCohortFromDraft(){
  const pending=S.cohortDeletion;if(!pending)return;
  if(pending.revision!==S.revision||S.remoteRevision!==null)throw Error('Workspace changed. Close this dialog and review the latest saved workspace before deleting.');
  const target=S.doc.cohorts.find(c=>c.id===pending.id);if(!target)return;
  S.doc.cohorts=S.doc.cohorts.filter(c=>c.id!==target.id);project().cohortIds=project().cohortIds.filter(id=>id!==target.id);
  for(const p of S.doc.pipelines){const aliases=Object.keys(p.cohorts).filter(alias=>p.cohorts[alias]===target.id);for(const alias of aliases)delete p.cohorts[alias];for(const stage of p.stages)if(stage.kind==='poll'&&aliases.includes(stage.cohort))stage.cohort='';}
  if(S.cohortId===target.id){S.cohortId=null;S.personId=null;}if(S.preferredCohortId===target.id)S.preferredCohortId=null;
  if(S.cohortTarget===target.id){S.cohortTarget=null;S.cohortPrompt='';}S.cohortComposer=false;S.cohortDeletion=null;S.plan=null;S.dirty=true;
  document.getElementById('deleteCohortDialog').close();render();say('Cohort removed from draft. Save changes to keep the deletion.');
}
function cohortCard(c){return listRow('open-cohort',c,'Open cohort: '+c.name,c.name,c.population,[plural(c.personas.length,'persona')],listDeleteButton('delete-cohort',c,'Delete cohort: '+c.name),'cohort-list-item','cohort-open')}

function cohorts(){const c=cohort();if(S.cohortComposer)return cohortGenerator();if(!c){const page=pageItems(projectCohorts(),'cohorts',viewportPageSize(6,4));const body=projectCohorts().length?'<div class="list">'+page.items.map(cohortCard).join('')+'</div>'+page.controls:emptyCreate('new-cohort','New cohort','Click anywhere here to describe an audience. Your drafting AI drafts its segments and personas, and the cohort is reusable across studies.');return header('Cohorts','The synthetic people your studies ask. Each cohort can serve several studies.',(S.dirty?saveButton():'')+(projectCohorts().length?'<button class="button primary" data-act="new-cohort">'+icon('plus')+'New cohort</button>':''))+tabs()+'<section id="view-cohorts" role="tabpanel" aria-labelledby="tab-cohorts">'+cohortJobNotice()+(cohortJobNoticeVisible()&&!projectCohorts().length?'':body)+'</section>'}if(S.personaOpen)return personaDetail(c);const content=cohortExplorer(c);const returnPipeline=projectPipelines().find(p=>p.id===S.cohortReturn?.pipelineId);
  const actions='<span id="cohortSaveState" class="save-state" role="status">'+(S.dirty?'Unsaved changes':'All changes saved')+'</span><div class="cohort-actions" role="group" aria-label="Cohort actions">'+saveButton()+'<button class="button danger icon-button" title="Delete cohort" aria-label="Delete cohort" data-act="delete-cohort" data-id="'+attr(c.id)+'">'+icon('trash')+'</button></div>';
  return '<div class="cohort-detail-page">'+focusedHeader(c.name||'Configure cohort',c.population||'Define an adult synthetic population.','Cohort editor',returnPipeline?'back-cohort-pipeline':'',returnPipeline?'Back to study':'',actions)+'<section id="view-cohort" aria-labelledby="view-title">'+content+'</section></div>';
}
function sourcesEditor(c){const page=pageItems(c.sources,'sources-'+c.id,1);const rows=page.items.map(s=>'<form data-form="source" data-id="'+attr(s.id)+'" class="item-card"><h3>'+esc(s.title||s.id)+'</h3><div class="grid2">'+field('Source ID','sourceId',s.id,'text','','',s.id)+field('Retrieved date','retrievedAt',(s.retrievedAt||'').slice(0,10),'date','','',s.id)+field('Title','sourceTitle',s.title,'text','','',s.id)+field('URL','sourceUrl',s.url,'url','','',s.id)+'</div>'+area('What this supports and its limitations','sourceNotes',s.notes,'','2',s.id)+'<div class="row"><button class="button small soft" type="submit">Apply source</button><button type="button" class="button small danger" data-act="remove-source" data-id="'+attr(s.id)+'">Remove source</button></div></form>').join('');return panel('Sources','Optional reference documents, such as surveys or reports, that support audience traits or group sizes.',rows+page.controls+'<button type="button" class="button small" data-act="add-source">＋ Add source</button>')}
