function reviewStep(p,item){
 const s=p.stages.find(x=>x.id===item.id),cohort=S.doc.cohorts.find(c=>c.id===p.cohorts[item.cohort]),n=id=>p.stages.findIndex(x=>x.id===id)+1;
 const title=s?flowNodeTitle(p,s):{title:item.label,sub:''},kind={poll:'Ask cohort',aggregate:'Combine',decision:'Final result'}[item.kind]||item.kind;
 const when=item.dependsOn.length?'After '+(item.dependsOn.length===1?'step ':'steps ')+item.dependsOn.map(n).join(', ')+(item.dependsOn.length>1&&s?.join==='any'?' (any one)':''):'Starts first';
 const who=item.kind==='poll'?(cohort?cohort.name+' · ':'')+(item.profiles!==undefined?plural(item.profiles,'persona')+((item.repeats||1)>1?' × '+item.repeats:''):''):item.kind==='aggregate'?'Weights the connected answers':'Picks the leading option, no model call';
 let details='';
 if(s){
  const parts=[];
  if(s.kind==='poll'){
   for(const q of Object.values(s.questions))parts.push((Object.keys(s.questions).length>1||q.label!==title.title?'<h4>'+esc(q.label)+'</h4>':'<h4>Question</h4>')+'<p class="subtle">'+esc(answerName(q.type))+(q.instructions?' · '+esc(q.instructions):'')+'</p>'+(q.criteria&&Object.keys(q.criteria).length?'<ul>'+Object.entries(q.criteria).map(([key,value])=>'<li>'+esc(typeof value==='object'&&value!==null?value.label+(value.description?': '+value.description:''):value||key)+'</li>').join('')+'</ul>':''));
   const inputs=s.inputs===undefined?s.dependsOn.map(id=>'Summary of step '+n(id)):Object.entries(s.inputs).map(([name,x])=>'Step '+n(x.stage)+' · '+({summary:'answer summary',responses:'each answer',winner:'leading option',mean:'mean score',probabilities:'distribution'}[x.select||'summary'])+' (as inputs.'+name+')');
   if(inputs.length)parts.push('<h4>Reads</h4><ul>'+inputs.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>');
   parts.push('<h4>Produces</h4><ul>'+Object.values(s.questions).map(q=>'<li>'+esc((Object.keys(s.questions).length>1?q.label+': ':'')+(q.type==='choice'?'a weighted share for each option':q.type==='score'?'a weighted mean score':'a weighted likelihood'))+'</li>').join('')+'</ul>');
   parts.push('<h4>Context sent with each request</h4><pre>'+esc(JSON.stringify({shared:p.context,step:s.context??null},null,2))+'</pre>');
  }else if(s.kind==='aggregate')parts.push('<h4>Reads</h4><ul>'+s.inputs.map(x=>'<li>Step '+n(x.stage)+' · weight '+esc(String(x.weight))+'</li>').join('')+'</ul><h4>Produces</h4><p>One combined result. '+(s.join==='any'?'Uses whichever inputs finish.':'Needs every input.')+'</p>');
  else parts.push('<h4>Reads</h4><ul><li>Step '+n(s.from.stage)+'</li></ul><h4>Produces</h4><p>The leading option, with no new model call.</p>');
  details='<details class="review-step-details" data-detail-key="review-step-'+attr(s.id)+'"><summary>What this step asks and reads</summary>'+parts.join('')+'</details>';
 }
 const size=requestSizeLine(item.budget,batchingLead(item));
 return '<article class="review-step"><div class="review-step-head"><span class="flow-number">'+(n(item.id)||S.plan.stages.indexOf(item)+1)+'</span><div class="review-step-title"><h3>'+esc(title.title)+'</h3>'+(title.sub?'<p>'+esc(title.sub)+'</p>':'')+'</div><span class="review-step-requests"><strong>'+item.requests.toLocaleString('en-US')+'</strong> '+(item.requests===1?'request':'requests')+'</span></div><p class="review-step-meta"><span class="review-kind">'+kind+'</span><span>'+esc(when)+'</span>'+(who?'<span>'+esc(who)+'</span>':'')+'</p>'+(s?.when?'<p class="review-rule"><strong>Runs only when</strong> '+esc(reviewCondition(p,s.when))+'</p>':'')+size+details+'</article>';
}
function review(){
  const p=pipeline();if(!p)return studies();if(!S.plan)return '<div class="panel">'+empty('Preparing run plan','The planner is checking step dependencies, panel sizes, and request limits.')+'</div>';
  const plan=S.plan,stagePage=pageItems(plan.stages,'run-plan',viewportPageSize(8,4));
  const stages=stagePage.items.map(s=>reviewStep(p,s)).join('');
  const steps='<section class="review-section" aria-label="Steps to run"><h2>Steps, in run order</h2>'+(stages?'<div class="review-steps">'+stages+'</div>':'<p>No steps are planned.</p>')+stagePage.controls+'</section>';
  const settings='<section class="review-section" aria-label="Run settings"><h2>Run settings</h2><form data-form="run-options" class="review-settings"><div class="grid3">'+field('Seed','seed',S.seed,'text','Same seed, same sampling.')+field('Concurrency','concurrency',S.concurrency,'number','Requests at once.','required min="1" step="1"')+field('Request limit','maxRequests',S.maxRequests,'number','Stops the run if reached.','required min="1" step="1"')+'</div></form></section>';
  const assumptions=plan.warnings.length?'<details class="review-caveats" data-detail-key="run-assumptions"><summary>Assumptions and model limits</summary><p>These notes describe missing sources, declared assumptions, and provider limits. They do not block this run or require dismissal. For exploratory runs, synthetic assumptions are expected.</p><p>For better grounding, use Edit study to change cohort sources and segment weights. Provider limits describe what the selected model can support.</p><ul>'+plan.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></details>':'';
  const actions='<button class="button" data-act="edit-review">Edit study</button><button type="button" class="button" data-act="evaluation-settings" '+(evaluationReady(plan.provider)?'hidden':'')+'>Set up evaluation provider</button><button type="button" class="button primary" data-act="start-run" '+(evaluationReady(plan.provider)?'':'disabled')+'>Run study</button>';
  const summary='<div class="run-review-summary"><div><strong>'+plural(plan.stages.length,'step')+'</strong><span>in run order</span></div><div><strong>Up to '+Number(plan.maxRequests||0).toLocaleString('en-US')+'</strong><span>model requests</span></div><div><strong>'+esc(evaluationProviderName(plan.provider))+'</strong><span>'+esc(plan.model)+(plan.provider==='gliner'?' · runs locally with GLiNER, no billing':' · billed to your TypeSafe account')+'</span></div>'+runCaveats(plan)+'</div>';
  return header('Review run',esc(studyQuestion(p)),actions)+'<section id="view-studies" class="run-review" aria-label="Run review">'+summary+steps+settings+assumptions+'</section>';
}
