function workspaceCounts(document,projectId=S.projectId){const owner=projectId?(document.projects||[]).find(x=>x.id===projectId):null,cohorts=owner?document.cohorts.filter(c=>owner.cohortIds.includes(c.id)):projectId?[]:document.cohorts,pipelines=owner?document.pipelines.filter(p=>owner.pipelineIds.includes(p.id)):projectId?[]:document.pipelines;return {pools:cohorts.length,personas:cohorts.reduce((n,c)=>n+c.personas.length,0),pipelines:pipelines.length,phases:pipelines.reduce((n,p)=>n+p.stages.length,0)}}
function proposalChanges(before,after){const sections=[{kind:'cohort',key:'cohorts',children:'personas',childLabel:'persona'},{kind:'study',key:'pipelines',children:'stages',childLabel:'step'}];const summaries=[],items=[];let removals=0;for(const section of sections){const old=before[section.key],next=after[section.key],oldById=new Map(old.map(x=>[x.id,x])),nextById=new Map(next.map(x=>[x.id,x]));const added=next.filter(x=>!oldById.has(x.id)),removed=old.filter(x=>!nextById.has(x.id)),changed=next.filter(x=>oldById.has(x.id)&&JSON.stringify(x)!==JSON.stringify(oldById.get(x.id)));summaries.push((section.kind==='cohort'?'Cohorts':'Studies')+': '+added.length+' added · '+changed.length+' changed · '+removed.length+' removed');for(const x of added)items.push('<li>Added '+section.kind+': <strong>'+esc(x.name)+'</strong> <code>('+esc(x.id)+')</code> · '+plural(x[section.children].length,section.childLabel)+'</li>');for(const x of changed){const previous=oldById.get(x.id),addedChildren=x[section.children].filter(child=>!previous[section.children].some(oldChild=>oldChild.id===child.id)).length,removedChildren=previous[section.children].filter(child=>!x[section.children].some(newChild=>newChild.id===child.id)).length;removals+=removedChildren;items.push('<li>Changed '+section.kind+': <strong>'+esc(previous.name)+(previous.name!==x.name?' → '+esc(x.name):'')+'</strong> <code>('+esc(x.id)+')</code>'+((addedChildren||removedChildren)?' · '+plural(addedChildren,section.childLabel)+' added · '+plural(removedChildren,section.childLabel)+' removed':'')+'</li>')}for(const x of removed){removals+=1+x[section.children].length;items.push('<li>Removed '+section.kind+': <strong>'+esc(x.name)+'</strong> <code>('+esc(x.id)+')</code> · '+x[section.children].length+' '+section.childLabel+' removed</li>')}}return '<div class="'+(removals?'warning':'notice')+'">'+summaries.map(esc).join('<br>')+(removals?'<br>Applying replaces the saved workspace, including the removals listed below.':'')+'</div>'+(items.length?'<ul class="proposal-items">'+items.join('')+'</ul>':'<p class="subtle">No workspace changes.</p>')}
function proposalReview(job){if(!job)return '';if(job.persona)return '<div class="notice">Individual persona task. <button class="button" data-act="persona-job-open">Review persona replacement</button></div>';if(job.cohort)return cohortProposalReview(job);if(job.status==='running')return draftProgress(job);if(job.status!=='completed'||!job.proposal)return panel(job.status==='cancelled'?'Preparation cancelled':'Preparation failed','', '<div class="warning">'+esc(job.message||'No proposal was returned.')+'</div>');const draft=job.proposal.document,before=workspaceCounts(S.doc),after=workspaceCounts(draft),stale=job.revision!==S.revision;return panel(S.proposalApplied?'Proposal applied':'Review proposed changes','Applying saves the new workspace. It does not start a poll.','<div class="proposal-explanation">'+markdownHtml(job.proposal.explanation)+'</div><dl class="proposal-summary" aria-label="Proposed changes"><div><dt>Cohorts</dt><dd>'+before.pools+' → '+after.pools+' <small>('+plural(after.personas,'persona')+')</small></dd></div><div><dt>Studies</dt><dd>'+before.pipelines+' → '+after.pipelines+'</dd></div><div><dt>Steps</dt><dd>'+before.phases+' → '+after.phases+'</dd></div></dl>'+proposalChanges(S.doc,draft)+'<details class="advanced" data-detail-key="proposal-json"><summary>Inspect complete proposed workspace</summary><textarea class="agent-code" aria-label="Proposed workspace JSON" readonly rows="16">'+esc(JSON.stringify(draft,null,2))+'</textarea></details>'+(S.proposalApplied?'<div class="toolbar"><button class="button primary" data-act="tab" data-tab="cohorts">Open cohorts</button><button class="button" data-act="tab" data-tab="studies">Open studies</button></div>':(stale?'<div class="warning">Workspace changed since this proposal began. Prepare a new proposal against the latest saved draft.</div>':'')+'<div class="toolbar"><button class="button primary" data-act="assistant-apply" '+(stale||S.dirty||S.remoteRevision!==null||S.localLoading?'disabled':'')+'>Apply proposal</button><button class="button" data-act="assistant-discard">Discard proposal</button></div>'))}
function agents(){const active=S.localStart||S.localJob,running=active?.status==='running';const drafting=panel('Draft a cohort or study','Describe what you need. Review proposed changes before applying them.','<form data-form="assistant"><fieldset '+(running?'disabled':'')+' style="border:0;padding:0;margin:0;min-width:0">'+'<div class="field"><label for="assistantPrompt">What should the assistant create or change?</label><textarea id="assistantPrompt" name="localPrompt" class="assistant-prompt" rows="6" placeholder="For example: Draft a cohort of adult Steam gamers and a study comparing names for my space strategy game.">'+esc(S.localPrompt)+'</textarea></div><p class="assistant-scope">Choose drafting AI with the AI button above. Current edits save before drafting. Include source facts; personas are synthetic assumptions. Drafting does not search the web or run a study.</p>'+'</fieldset><div class="row generation-actions"><button class="button primary" data-act="assistant-generate" type="button" '+(!draftReady()||!S.localPrompt.trim()||S.remoteRevision!==null||running||S.localLoading?'disabled':'')+'>'+(running?'Drafting changes…':'Draft changes')+'</button>'+draftCancelButton(active)+'</div></form>'+(S.localError?'<div class="warning" role="alert">'+esc(S.localError)+'</div>':''));const content=sectionPanels('assistant',[{id:'draft',label:'Request',html:drafting},{id:'proposal',label:running?'Progress':'Proposed changes',html:proposalReview(active)||empty('No proposed changes yet','Describe what you need in Request, then choose Draft changes. You can review the result before applying it.')}]);return header('Assistant','Create or refine your project’s cohorts, questions, and study flow.','<button class="button" data-act="refresh">Refresh workspace</button>')+tabs()+'<section id="view-agents" role="tabpanel" aria-labelledby="tab-agents"><div class="generation-workspace assistant-workspace">'+content+'</div></section>'}
/** After a reload, an audience draft started from a step brings the user back to that step's "Who answers" stop instead of a list page. */
